package com.hbm.client.solarboiler;
import com.hbm.machine.solarboiler.SolarBoilerContent;import java.util.List;import mezz.jei.api.*;import mezz.jei.api.constants.VanillaTypes;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.recipe.*;import mezz.jei.api.recipe.category.IRecipeCategory;import mezz.jei.api.registration.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;
@JeiPlugin public final class SolarBoilerJeiPlugin implements IModPlugin {
 private static final RecipeType<SolarBoilerViews.View> TYPE=RecipeType.create("hbm","solar_boiler",SolarBoilerViews.View.class);
 @Override public ResourceLocation getPluginUid(){return ResourceLocation.parse("hbm:solar_boiler_jei");}@Override public void registerCategories(IRecipeCategoryRegistration event){event.addRecipeCategories(new Category(event.getJeiHelpers().getGuiHelper()));}@Override public void registerRecipes(IRecipeRegistration event){event.addRecipes(TYPE,List.of(SolarBoilerViews.view()));}@Override public void registerRecipeCatalysts(IRecipeCatalystRegistration event){for(var item:java.util.List.of(SolarBoilerContent.BOILER_ITEM,SolarBoilerContent.MIRROR_ITEM))event.addRecipeCatalysts(TYPE,item.get());}@Override public void registerExtraIngredients(IExtraIngredientRegistration event){event.addExtraIngredients(VanillaTypes.ITEM_STACK,SolarBoilerContent.allStacks());}
 private static final class Category implements IRecipeCategory<SolarBoilerViews.View>{private final IDrawable background,icon;Category(IGuiHelper helper){background=helper.createBlankDrawable(166,65);icon=helper.createDrawableItemStack(SolarBoilerContent.allStacks().getFirst());}@Override public RecipeType<SolarBoilerViews.View> getRecipeType(){return TYPE;}@Override public Component getTitle(){return Component.translatable("block.hbm.machine_solar_boiler");}@Override public IDrawable getBackground(){return background;}@Override public IDrawable getIcon(){return icon;}@Override public void setRecipe(IRecipeLayoutBuilder builder,SolarBoilerViews.View recipe,IFocusGroup focus){builder.addSlot(RecipeIngredientRole.INPUT,30,24).addItemStack(recipe.input());builder.addSlot(RecipeIngredientRole.OUTPUT,102,24).addItemStack(recipe.output());}@Override public void draw(SolarBoilerViews.View recipe,IRecipeSlotsView slots,GuiGraphics g,double x,double y){SolarBoilerViews.draw(g,0,0);}}
}
